"""
demo.py — Numerical demonstrations of the Log-Free EML Differential Algebra.

The log-free EML class is the smallest class of functions R -> R containing
constants and the identity and closed under (+), (*), and post-composition with
exp.  We model it by an inductive term algebra:

    Term ::= Const c | Id | Add a b | Mul a b | Exp a

with an evaluation map `eval`, a syntactic derivative `D` (which satisfies
deriv(eval t) = eval(D t)), and a substitution operator `comp` (which satisfies
eval(comp u v) = eval(u) . eval(v)).

This file is fully self-contained: every function used is inlined below, and the
demonstrations cross-check the symbolic operations against direct numerical
calculus (finite differences and known closed forms).

Run:  python demo.py
"""

from __future__ import annotations

from dataclasses import dataclass
from math import exp as _exp, erf, sqrt, pi
from typing import Callable, List, Tuple


# --------------------------------------------------------------------------- #
# 1. The term algebra                                                         #
# --------------------------------------------------------------------------- #

class Term:
    """Base class for EML terms (an algebraic data type)."""
    pass


@dataclass(frozen=True)
class Const(Term):
    c: float


@dataclass(frozen=True)
class Id(Term):
    pass


@dataclass(frozen=True)
class Add(Term):
    a: Term
    b: Term


@dataclass(frozen=True)
class Mul(Term):
    a: Term
    b: Term


@dataclass(frozen=True)
class Exp(Term):
    a: Term


# --------------------------------------------------------------------------- #
# 2. Evaluation:  eval : Term -> (float -> float)                             #
# --------------------------------------------------------------------------- #

def eval_term(t: Term, x: float) -> float:
    """Evaluate the function denoted by term `t` at the point `x`."""
    if isinstance(t, Const):
        return t.c
    if isinstance(t, Id):
        return x
    if isinstance(t, Add):
        return eval_term(t.a, x) + eval_term(t.b, x)
    if isinstance(t, Mul):
        return eval_term(t.a, x) * eval_term(t.b, x)
    if isinstance(t, Exp):
        return _exp(eval_term(t.a, x))
    raise TypeError(f"unknown term: {t!r}")


def as_function(t: Term) -> Callable[[float], float]:
    """Return the Python function x |-> eval(t)(x)."""
    return lambda x: eval_term(t, x)


# --------------------------------------------------------------------------- #
# 3. Symbolic derivative:  D : Term -> Term                                   #
# --------------------------------------------------------------------------- #

def D(t: Term) -> Term:
    """The syntactic (formal) derivative, mirroring the rules of calculus."""
    if isinstance(t, Const):
        return Const(0.0)
    if isinstance(t, Id):
        return Const(1.0)
    if isinstance(t, Add):
        return Add(D(t.a), D(t.b))
    if isinstance(t, Mul):                       # Leibniz rule
        return Add(Mul(D(t.a), t.b), Mul(t.a, D(t.b)))
    if isinstance(t, Exp):                       # chain rule for e^a
        return Mul(D(t.a), Exp(t.a))
    raise TypeError(f"unknown term: {t!r}")


# --------------------------------------------------------------------------- #
# 4. Substitution / composition:  comp : Term -> Term -> Term                #
# --------------------------------------------------------------------------- #

def comp(outer: Term, inner: Term) -> Term:
    """Replace every Id-leaf of `outer` by `inner` (realizing composition)."""
    if isinstance(outer, Const):
        return outer
    if isinstance(outer, Id):
        return inner
    if isinstance(outer, Add):
        return Add(comp(outer.a, inner), comp(outer.b, inner))
    if isinstance(outer, Mul):
        return Mul(comp(outer.a, inner), comp(outer.b, inner))
    if isinstance(outer, Exp):
        return Exp(comp(outer.a, inner))
    raise TypeError(f"unknown term: {outer!r}")


# --------------------------------------------------------------------------- #
# 5. Pretty printing and size                                                 #
# --------------------------------------------------------------------------- #

def show(t: Term) -> str:
    """A readable infix rendering of a term."""
    if isinstance(t, Const):
        c = t.c
        return f"{c:g}"
    if isinstance(t, Id):
        return "x"
    if isinstance(t, Add):
        return f"({show(t.a)} + {show(t.b)})"
    if isinstance(t, Mul):
        return f"({show(t.a)} * {show(t.b)})"
    if isinstance(t, Exp):
        return f"exp({show(t.a)})"
    raise TypeError(f"unknown term: {t!r}")


def size(t: Term) -> int:
    """Number of nodes in the term tree."""
    if isinstance(t, (Const, Id)):
        return 1
    if isinstance(t, (Add, Mul)):
        return 1 + size(t.a) + size(t.b)
    if isinstance(t, Exp):
        return 1 + size(t.a)
    raise TypeError(f"unknown term: {t!r}")


# --------------------------------------------------------------------------- #
# 6. Numerical reference: central finite difference                           #
# --------------------------------------------------------------------------- #

def numeric_deriv(f: Callable[[float], float], x: float, h: float = 1e-6) -> float:
    """Central finite-difference approximation of f'(x)."""
    return (f(x + h) - f(x - h)) / (2.0 * h)


# --------------------------------------------------------------------------- #
# 7. Convenience constructors for sample EML functions                        #
# --------------------------------------------------------------------------- #

def poly_x_squared() -> Term:
    """x^2 = x * x."""
    return Mul(Id(), Id())


def gaussian() -> Term:
    """e^{-x^2}, the prototypical EML function with no EML antiderivative."""
    return Exp(Mul(Const(-1.0), Mul(Id(), Id())))


def damped() -> Term:
    """x * e^{-x}: a damped envelope."""
    return Mul(Id(), Exp(Mul(Const(-1.0), Id())))


# --------------------------------------------------------------------------- #
# Demonstrations                                                              #
# --------------------------------------------------------------------------- #

def demo_fundamental_theorem() -> None:
    """Check deriv(eval t) = eval(D t) against finite differences."""
    print("=" * 70)
    print("DEMO 1  Fundamental theorem of the EML calculus:  (eval t)' = eval(D t)")
    print("=" * 70)
    terms: List[Tuple[str, Term]] = [
        ("x^2", poly_x_squared()),
        ("e^{-x^2}  (Gaussian)", gaussian()),
        ("x e^{-x}  (damped)", damped()),
        ("e^{e^x}   (tower)", Exp(Exp(Id()))),
    ]
    pts = [-1.3, -0.4, 0.0, 0.7, 1.5]
    for name, t in terms:
        dt = D(t)
        print(f"\n  f(x) = {name}")
        print(f"  D(term) = {show(dt)}")
        print(f"  {'x':>6} {'eval(D t)(x)':>16} {'numeric f''(x)':>16} {'|diff|':>12}")
        f = as_function(t)
        df = as_function(dt)
        for x in pts:
            symbolic = df(x)
            numeric = numeric_deriv(f, x)
            print(f"  {x:6.2f} {symbolic:16.8f} {numeric:16.8f} "
                  f"{abs(symbolic - numeric):12.2e}")


def demo_composition() -> None:
    """Check eval(comp u v) = eval(u)(eval(v)(x))."""
    print("\n" + "=" * 70)
    print("DEMO 2  Substitution computes composition:  eval(comp u v) = u . v")
    print("=" * 70)
    examples: List[Tuple[str, Term, Term]] = [
        ("u = e^x, v = -x^2  =>  e^{-x^2}",
         Exp(Id()), Mul(Const(-1.0), Mul(Id(), Id()))),
        ("u = x^2, v = e^x   =>  e^{2x}",
         Mul(Id(), Id()), Exp(Id())),
    ]
    pts = [-1.0, 0.0, 0.5, 1.2]
    for name, u, v in examples:
        c = comp(u, v)
        fu, fv = as_function(u), as_function(v)
        fc = as_function(c)
        print(f"\n  {name}")
        print(f"  comp(u, v) = {show(c)}")
        print(f"  {'x':>6} {'eval(comp)':>16} {'u(v(x))':>16} {'|diff|':>12}")
        for x in pts:
            lhs = fc(x)
            rhs = fu(fv(x))
            print(f"  {x:6.2f} {lhs:16.8f} {rhs:16.8f} {abs(lhs - rhs):12.2e}")


def demo_ring_closure() -> None:
    """Demonstrate that +, -, * of EML functions are realized by terms."""
    print("\n" + "=" * 70)
    print("DEMO 3  Ring closure: sums, differences, products stay EML")
    print("=" * 70)
    f = damped()              # x e^{-x}
    g = gaussian()            # e^{-x^2}
    add_term = Add(f, g)
    # subtraction is derived: f - g = f + (-1)*g
    sub_term = Add(f, Mul(Const(-1.0), g))
    mul_term = Mul(f, g)
    pts = [-0.5, 0.0, 1.0, 2.0]
    ff, gg = as_function(f), as_function(g)
    print(f"  f(x) = {show(f)}")
    print(f"  g(x) = {show(g)}")
    print(f"\n  {'x':>6} {'(f+g) term':>14} {'f+g direct':>14}"
          f" {'(f*g) term':>14} {'f*g direct':>14}")
    fa, fs, fm = as_function(add_term), as_function(sub_term), as_function(mul_term)
    for x in pts:
        print(f"  {x:6.2f} {fa(x):14.8f} {ff(x) + gg(x):14.8f}"
              f" {fm(x):14.8f} {ff(x) * gg(x):14.8f}")
    # quick consistency check on subtraction term
    assert all(abs(fs(x) - (ff(x) - gg(x))) < 1e-12 for x in pts)
    print("\n  (subtraction term f + (-1)*g matches f - g to < 1e-12)")


def demo_iterated_derivatives() -> None:
    """Differentiate repeatedly; the result is always an EML term."""
    print("\n" + "=" * 70)
    print("DEMO 4  Closure under differentiation: iterate D and watch term size")
    print("=" * 70)
    t = gaussian()            # e^{-x^2}
    print(f"  start: f(x) = {show(t)}  (size {size(t)})")
    cur = t
    for k in range(1, 5):
        cur = D(cur)
        print(f"  D^{k} f  has term size {size(cur)};  value at x=0.5: "
              f"{eval_term(cur, 0.5):.8f}")
    print("  Each derivative is again an EML term (closure under d/dx).")


def demo_integration_boundary() -> None:
    """Illustrate the integration boundary: e^{-x^2} vs its (non-EML) integral."""
    print("\n" + "=" * 70)
    print("DEMO 5  Integration boundary (Liouville): integral of e^{-x^2}")
    print("=" * 70)
    f = gaussian()
    ff = as_function(f)
    # Numerically integrate via the trapezoidal rule from 0 to b; compare to
    # the closed form (sqrt(pi)/2) * erf(b), whose antiderivative (erf) is NOT EML.
    def trapz(a: float, b: float, n: int = 20000) -> float:
        h = (b - a) / n
        s = 0.5 * (ff(a) + ff(b))
        for i in range(1, n):
            s += ff(a + i * h)
        return s * h

    print(f"  f(x) = {show(f)}")
    print(f"  Antiderivative is (sqrt(pi)/2)*erf(x): NOT an EML function.")
    print(f"\n  {'b':>6} {'trapz int_0^b':>18} {'(sqrt(pi)/2) erf(b)':>22} {'|diff|':>12}")
    for b in [0.5, 1.0, 1.5, 2.0]:
        approx = trapz(0.0, b)
        closed = 0.5 * sqrt(pi) * erf(b)
        print(f"  {b:6.2f} {approx:18.10f} {closed:22.10f} {abs(approx - closed):12.2e}")
    print("\n  The integral exists and is smooth, but no EML term denotes it:")
    print("  this is the (conjectural) non-surjectivity of the derivation D.")


def main() -> None:
    demo_fundamental_theorem()
    demo_composition()
    demo_ring_closure()
    demo_iterated_derivatives()
    demo_integration_boundary()
    print("\nAll demonstrations completed.")


if __name__ == "__main__":
    main()
